// БАГ: не проверяем res.ok
async function bad() {
  const res = await fetch("/not-found");  // 404!
  const data = await res.json();  // парсим страницу ошибки...
  console.log(data.user.name);  // TypeError — undefined!
}

// ПРАВИЛЬНО: проверяем ok
async function good() {
  const res = await fetch("/api/users");
  if (!res.ok) {
    throw new Error(`HTTP error! status: ${res.status}`);
  }
  const data = await res.json();  // теперь точно данные
  return data;
}

async function createUser(name) {
  const response = await fetch("/api/users", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name })  // объект → строка JSON
  });
  if (!response.ok) throw new Error("Failed");
  return response.json();  // сервер вернул созданного пользователя
}

// Мок-функция, имитирующая fetch
function mockFetch(url) {
  // Возвращаем Promise с объектом похожим на Response
  return Promise.resolve({
    ok: true,           // статус успешный
    status: 200,        // код ответа
    json: () => Promise.resolve({ id: 1, name: "Alice" })
  });
}

// Работает точно как настоящий fetch!
async function load() {
  const res = await mockFetch("/api/users");
  const data = await res.json();
  console.log(data.name);  // Alice
}

async function safeFetch(url) {
  try {
    const res = await fetch(url);
    if (!res.ok) {
      // Ошибка сервера — бросаем сами
      throw new Error(`HTTP ${res.status}`);
    }
    return await res.json();
  } catch (error) {
    // Сетевая ошибка ИЛИ наш throw
    console.error("Запрос не удался:", error.message);
    return null;
  }
}

// Параллельно: загрузка пользователей И постов одновременно
const [users, posts] = await Promise.all([
  fetch("/api/users").then(r => r.json()),
  fetch("/api/posts").then(r => r.json())
]);

console.log(users);  // массив пользователей
console.log(posts);  // массив постов

